import * as T from './vendor/three.module.js';
import {createNeighbors} from './neighbors-core.js';
export function installResidents({scene,camera,colliders,villages,pause,guideTo,rewards,guideRewards}){
 const people=[{id:'meadow',name:'Rowan',color:'#648055',skin:'#b87b54',x:-43.5,z:97,greeting:'Welcome to Meadow Village! The cottages are open for visits. Find a favorite, then settle into the picnic garden.',tip:'Try a garden bench, enjoy the flowers, and visit one of our three cream cottages.'},{id:'harbor',name:'Mira',color:'#397c9a',skin:'#d2a17c',x:43.5,z:97,greeting:'Hello from Bluewater Village! Take a look inside our blue-trimmed homes, or slow down beside the reflecting pond.',tip:'Bluewater Terrace is a quiet place to sit. The tram stop is on the path north of the village rewards station.'},{id:'woodland',name:'Fern',color:'#74543e',skin:'#845638',x:-28.5,z:127,greeting:'Welcome to Woodland Village. Our timber cabins and lantern circle are ready for you to explore.',tip:'Gather around the lanterns, visit a cabin, or take the tram back to the park entrance.'}];
 const neighbors=createNeighbors({getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v)});for(const p of people)p.met=neighbors.state().met.includes(p.id);
 const material=color=>new T.MeshStandardMaterial({color,roughness:.8}),cream=material('#f3dfb4'),dark=material('#263234');
 for(const p of people){const root=new T.Group();root.name=p.name+' · Village host';root.position.set(p.x,0,p.z);scene.add(root);p.root=root;const outfit=material(p.color),skin=material(p.skin);
  function mesh(g,m,x,y,z,parent=root){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o;}
  mesh(new T.CylinderGeometry(.27,.36,.85,12),outfit,0,1.08,0);mesh(new T.SphereGeometry(.27,14,10),skin,0,1.8,0);mesh(new T.CylinderGeometry(.4,.4,.09,16),cream,0,2.04,0);mesh(new T.CylinderGeometry(.26,.28,.25,16),outfit,0,2.17,0);
  for(const s of [-1,1]){mesh(new T.CylinderGeometry(.1,.1,.65,8),dark,s*.18,.36,0);mesh(new T.SphereGeometry(.045,8,6),dark,s*.1,1.83,.24);}
  const arm=new T.Group();arm.position.set(.35,1.4,0);root.add(arm);mesh(new T.CylinderGeometry(.085,.085,.55,8),outfit,0,-.25,0,arm);mesh(new T.SphereGeometry(.1,8,6),skin,0,-.55,0,arm);p.arm=arm;mesh(new T.CylinderGeometry(.085,.085,.65,8),outfit,-.4,1.05,0);
  const canvas=document.createElement('canvas');canvas.width=512;canvas.height=160;const ctx=canvas.getContext('2d');ctx.fillStyle=p.color;ctx.fillRect(0,0,512,160);ctx.fillStyle='#fff4d8';ctx.textAlign='center';ctx.font='bold 44px serif';ctx.fillText(p.name,256,67);ctx.font='28px sans-serif';ctx.fillText('VILLAGE HOST',256,124);const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;mesh(new T.PlaneGeometry(2,.63),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),0,2.8,0);colliders.push({x:p.x,z:p.z,r:.55});
 }
 const dialog=document.createElement('dialog');dialog.id='residentMenu';dialog.setAttribute('aria-labelledby','residentTitle');const title=document.createElement('h2');title.id='residentTitle';const speech=document.createElement('p');speech.id='residentSpeech';speech.setAttribute('aria-live','polite');const status=document.createElement('p');status.id='residentQuest';const actions=document.createElement('div');actions.id='residentActions';const close=document.createElement('button');close.id='residentClose';close.textContent='Goodbye';close.onclick=()=>dialog.close();dialog.append(title,speech,status,actions,close);document.body.append(dialog);
 const style=document.createElement('link');style.rel='stylesheet';style.href='residents.css';document.head.append(style);
 const welcome=document.createElement('p');welcome.id='neighborProgress';welcome.setAttribute('aria-live','polite');dialog.replaceChildren(title,speech,welcome,status,actions,close);
 const nearest=()=>people.find(p=>Math.hypot(camera.position.x-p.x,camera.position.z-p.z)<2.8)||null;
 function open(){const p=nearest();if(!p)return false;pause();title.textContent='Meet '+p.name;speech.textContent=p.greeting;actions.replaceChildren();const st=rewards();status.textContent=st.claims.includes(p.id+':task')?'Your village home-visit reward is already collected.':st.done.includes('visit-'+p.id)?'Your home visit is complete. Collect 20 points at the village rewards station.':'Village welcome task: step inside any local home, then collect 20 points at the village rewards station.';
  function button(text,id,fn){const b=document.createElement('button');b.id=id;b.textContent=text;b.onclick=fn;actions.append(b);}
  neighbors.meet(p.id);p.met=true;const progress=neighbors.state();welcome.textContent=(progress.complete?'Village Welcome Pennant earned! Choose it for your home display in Villages & homes.':'Meet your neighbors: '+progress.met.length+' / 3 hosts greeted. Meet all three to earn a Village Welcome Pennant.')+(progress.saved?' Progress saved on this browser.':' Storage unavailable: progress lasts for this visit.');
  const remainingHosts=people.filter(h=>!h.met).sort((a,b)=>Math.hypot(a.x-camera.position.x,a.z-camera.position.z)-Math.hypot(b.x-camera.position.x,b.z-camera.position.z));if(remainingHosts.length)welcome.textContent+=' Still to meet: '+remainingHosts.map(h=>h.name).join(', ')+'.';const nextHost=remainingHosts[0];if(nextHost)button('Meet '+nextHost.name+' next','residentNextHost',()=>{guideTo({x:nextHost.x,z:nextHost.z+1.5,name:nextHost.name+' · Village host'});dialog.close();});else button('Open my home display','residentDisplay',()=>{dialog.close();villages.open();});
  button('What can I do here?','residentTips',()=>speech.textContent=p.tip);
  button('How do I make a home my own?','residentHomeHelp',()=>speech.textContent='Walk inside a home and press E. Choose it as your home base in Villages & homes. That menu also offers furniture colors, a display for earned lounge souvenirs, and Guide me home. Your choices are saved on this browser.');
  button('Show me a home','residentHome',()=>{const h=villages.homes.find(h=>h.village===p.id);guideTo({...h.door,name:h.name});dialog.close();});
  button('Show me the gathering place','residentCommons',()=>{const c=villages.commons.find(c=>c.id===p.id);guideTo({x:c.x,z:c.z+5,name:c.name});dialog.close();});
  button('Guide me to village rewards','residentRewards',()=>{guideRewards(p.id);dialog.close();});dialog.showModal();return true;
 }
 return {people,open,collection:neighbors.collection,progress:neighbors.state,get near(){return nearest()},get isOpen(){return dialog.open},update(ms){for(const p of people){const d=Math.hypot(camera.position.x-p.x,camera.position.z-p.z);if(d<12)p.root.rotation.y=Math.atan2(camera.position.x-p.x,camera.position.z-p.z);p.arm.rotation.z=d<5?2.4+Math.sin(ms*.004)*.22:.08;p.root.position.y=Math.sin(ms*.0015)*.015;}}};
}
